    } else if ("pay".equals(action)) {
        if (order.getState() == OrderState.PENDING) {
            // 支付逻辑
            order.setState(OrderState.PAID);
        }
    } // ... 更多if-else
}

// 状态机处理（结构清晰）
stateMachine.processEvent(order, OrderEvent.valueOf(action.toUpperCase()));
