// 🎯 2. React组件XSS防护
const SafeHtmlComponent = ({ htmlContent }: SafeHtmlProps) => {
  const sanitizedContent = useMemo(() => {
    return { __html: sanitizeHtml(htmlContent) }
  }, [htmlContent])

  return <div dangerouslySetInnerHTML={sanitizedContent} />
}

// 🎯 3. URL参数安全处理
const getSafeUrlParam = (paramName: string): string | null => {
  const url = new URL(window.location.href)
  const param = url.searchParams.get(paramName)

  if (!param) return null

  // 只允许安全的字符
  const safePattern = /^[a-zA-Z0-9\-_.]+$/
  return safePattern.test(param) ? param : null
}

// 🎯 4. 动态脚本安全加载
const loadScriptSafely = (src: string): Promise<void> => {
  return new Promise((resolve, reject) => {
    // 验证URL安全性
    const url = new URL(src, window.location.origin)
    if (url.protocol !== 'https:') {
      reject(new Error('只允许HTTPS脚本'))
      return
    }

    const script = document.createElement('script')
    script.src = src
    script.integrity = 'sha256-...' // SRI完整性检查
    script.crossOrigin = 'anonymous'

    script.onload = () => resolve()
    script.onerror = () => reject(new Error('脚本加载失败'))

    document.head.appendChild(script)
  })
}
