#### 🔑 认证安全策略

```typescript
// ✅ 前端认证安全最佳实践
class AuthManager {
  private tokenKey = 'auth_token'
  private refreshTokenKey = 'refresh_token'

  // 安全存储token
  setTokens(accessToken: string, refreshToken: string) {
    // 使用httpOnly cookie存储敏感token（推荐后端处理）
    // 前端仅存储非敏感信息
    sessionStorage.setItem(this.tokenKey, accessToken)
    localStorage.setItem(this.refreshTokenKey, refreshToken)
  }

  getAccessToken(): string | null {
    return sessionStorage.getItem(this.tokenKey)
  }

  // 自动刷新token
  async refreshAccessToken(): Promise<string | null> {
    const refreshToken = localStorage.getItem(this.refreshTokenKey)
    if (!refreshToken) return null

    try {
      const response = await fetch('/api/auth/refresh', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${refreshToken}`
        }
      })

      if (response.ok) {
        const data = await response.json()
        this.setTokens(data.accessToken, data.refreshToken)
        return data.accessToken
      }

      // 刷新失败，清除所有token
      this.clearTokens()
      return null
    } catch (error) {
      this.clearTokens()
      return null
    }
  }

  clearTokens() {
    sessionStorage.removeItem(this.tokenKey)
    localStorage.removeItem(this.refreshTokenKey)
  }

  // 检查token是否即将过期
  isTokenExpiringSoon(token: string): boolean {
    try {
      const payload = JSON.parse(atob(token.split('.')[1]))
      const expirationTime = payload.exp * 1000
      const currentTime = Date.now()
      const timeUntilExpiry = expirationTime - currentTime

      // 如果token在5分钟内过期，认为即将过期
      return timeUntilExpiry < 5 * 60 * 1000
    } catch {
      return true // 解析失败认为token无效
    }
  }
}

// 🎯 React认证Hook
export function useAuth() {
  const [authManager] = useState(() => new AuthManager())
  const [isAuthenticated, setIsAuthenticated] = useState(false)
  const [user, setUser] = useState<User | null>(null)

  useEffect(() => {
    const token = authManager.getAccessToken()
    if (token && !authManager.isTokenExpiringSoon(token)) {
      setIsAuthenticated(true)
      // 验证token并获取用户信息
      validateToken(token)
    } else if (token && authManager.isTokenExpiringSoon(token)) {
      // 自动刷新token
      authManager.refreshAccessToken().then(newToken => {
        if (newToken) {
          validateToken(newToken)
        } else {
          setIsAuthenticated(false)
          setUser(null)
        }
      })
    }
  }, [])

  const validateToken = async (token: string) => {
    try {
      const response = await fetch('/api/auth/verify', {
        headers: { 'Authorization': `Bearer ${token}` }
      })

      if (response.ok) {
        const userData = await response.json()
        setUser(userData)
        setIsAuthenticated(true)
      } else {
        throw new Error('Token验证失败')
      }
    } catch {
      setIsAuthenticated(false)
      setUser(null)
    }
  }

  return { isAuthenticated, user, authManager }
}
```

