        const ignorableInTests = [
            'unused-variable',
            'console-statement',
            'magic-number'
        ];

        return !ignorableInTests.includes(issue.rule);
    }

    isInTestFile(filePath) {
        return filePath.includes('/test/') ||
               filePath.includes('/spec/') ||
               filePath.endsWith('Test.java') ||
               filePath.endsWith('.test.js');
    }
}
