// Java 17：Switch表达式正式版 - 完全标准化
public class SwitchExpressionJava17 {

    // 1. 基本Switch表达式
    public static String getDayName(int day) {
        return switch (day) {
            case 1 -> "Monday";
            case 2 -> "Tuesday";
            case 3 -> "Wednesday";
            case 4 -> "Thursday";
            case 5 -> "Friday";
            case 6 -> "Saturday";
            case 7 -> "Sunday";
