// Java 14：Switch表达式 - 简洁而强大
public class SwitchExampleJava14 {

    // 1. 基本Switch表达式 - 箭头语法
    public static String getDayName(int day) {
        return switch (day) {
            case 1 -> "Monday";
            case 2 -> "Tuesday";
            case 3 -> "Wednesday";
            case 4 -> "Thursday";
            case 5 -> "Friday";
            case 6 -> "Saturday";
            case 7 -> "Sunday";
            default -> "Invalid day";
        };
    }

    // 2. 多值case - 更简洁的分组
    public static String getSeason(int month) {
        return switch (month) {
            case 12, 1, 2 -> "Winter";
            case 3, 4, 5 -> "Spring";
            case 6, 7, 8 -> "Summer";
            case 9, 10, 11 -> "Autumn";
            default -> "Invalid month";
        };
    }

    // 3. 复杂表达式作为返回值
    public static int getDaysInMonth(int month, boolean isLeapYear) {
        return switch (month) {
            case 1, 3, 5, 7, 8, 10, 12 -> 31;
            case 4, 6, 9, 11 -> 30;
            case 2 -> isLeapYear ? 29 : 28;
            default -> throw new IllegalArgumentException("Invalid month: " + month);
        };
    }

    // 4. 代码块语法 - 处理复杂逻辑
    public static String processOrder(OrderStatus status, boolean isVip) {
        return switch (status) {
            case PENDING -> {
                System.out.println("Processing pending order");
                yield "Order is pending";
            }
            case PROCESSING -> {
                String prefix = isVip ? "VIP" : "Regular";
                yield prefix + " order processing";
            }
            case COMPLETED -> {
                if (isVip) {
                    System.out.println("VIP order completed with bonus");
                    yield "VIP order completed with bonus";
                } else {
                    yield "Order completed";
                }
            }
            case CANCELLED -> "Order cancelled";
            default -> "Unknown status";
        };
    }

    // 5. 类型模式匹配结合Switch
    public static String describeObject(Object obj) {
        return switch (obj) {
            case String s -> "String: " + s;
            case Integer i -> "Integer: " + i;
            case Double d -> "Double: " + d;
            case List<?> list -> "List with " + list.size() + " elements";
            case null -> "Null object";
            default -> "Unknown type: " + obj.getClass().getSimpleName();
        };
    }

    // 6. 枚举的Switch表达式
    public static String getTrafficLightAction(TrafficLight light) {
        return switch (light) {
            case RED -> "Stop";
            case YELLOW -> "Caution";
            case GREEN -> "Go";
        };
    }

    // 7. 模式匹配的卫语句
