            if (constructorParams.length() > 0) {
                constructorParams.append(", ");
            }
            constructorParams.append("String ").append(field);

            constructorBody.append("""
                this.%s = %s;
                """.formatted(field, field));

            if (toStringBody.length() > 0) {
                toStringBody.append(" + \", \" + ");
            }
            toStringBody.append("""
