// instanceof模式匹配最佳实践
public class InstanceofBestPractices {

    // ✅ 推荐：简单的类型检查和转换
    public static String processSimple(Object obj) {
        if (obj instanceof String str) {
            return "String: " + str.toUpperCase();
        } else if (obj instanceof Integer num) {
            return "Integer: " + (num * 2);
        } else {
            return "Other type";
        }
