// 文件操作最佳实践
public class FileOperationsBestPractices {

    // ✅ 推荐：使用Java 11文件方法
    public static void modernFileOperations() throws IOException {
        Path configPath = Paths.get("config.properties");
        Path logPath = Paths.get("app.log");

