            xxlJobInfo.setTriggerStatus(1);
            this.updateById(xxlJobInfo);
            XxlJobHelper.log("更新下一次cron时间"+nextCron);
        }catch (Exception e){
            log.error("cron解析异常",e);
        }
    }
}

